REAL_NEVER_REACHED_PREFIX = "\r\n\r\nIP27 PROM SGI Version 6.11  built 03:19:48 PM Apr 29, 1998\r\nusing BaseIO nic\r\nTesting/Initializing memory ...............\t\tDONE\r\nCopying PROM code to memory ...............\t\tDONE\r\nDiscovering local IO ......................\t\tDONE\r\nupdate_klcfg_cpuinfo: Couldn't find my structure.\r\nDiscovering CrayLink connectivity .........\t\t\r\nLocal hub CrayLink is down.\r\n*** Local network link down\r\nDONE\r\nFound 1 objects (1 hubs, 0 routers) in 2125 usec\r\nWaiting for peers to complete discovery....\t\tDONE\r\nNo other nodes present; becoming global master\r\nGlobal master is /hw/module/0/slot/MotherBoard\r\nTesting/Initializing all memory ...........\t\tDONE\r\nChecking partitioning information .........\t\tDONE\r\nNo other nodes present; becoming partition master\r\n"


class MemoryVerdictTests(unittest.TestCase):
    def test_the_real_pass_transcript_passes(self):
        report = verdict(REAL_MEMORY_PASS_TRANSCRIPT, reached=True)
        self.assertEqual(report["problems"], [])
        self.assertEqual(report["verdict"], "PASS")

    def test_the_counts_hold_on_both_real_runs(self):
        self.assertEqual(count_problems(REAL_MEMORY_PASS_TRANSCRIPT), [])
        self.assertEqual(count_problems(REAL_FLAT_NAME_TRANSCRIPT), [])

    def test_a_flat_netboot_fails_on_the_path_assertion_alone(self):
        report = verdict(REAL_FLAT_NAME_TRANSCRIPT, reached=True)
        self.assertEqual(report["verdict"], "FAIL")
        self.assertEqual(report["problems"],
                         ["missing path-structured netboot fetch"])

    def test_no_real_run_carries_a_failure_marker(self):
        self.assertEqual(
            failure_markers_present(REAL_MEMORY_PASS_TRANSCRIPT), [])
        self.assertEqual(
            failure_markers_present(REAL_FLAT_NAME_TRANSCRIPT), [])

    def test_an_early_death_misses_every_test_start(self):
        missing = missing_assertions(REAL_NEVER_REACHED_PREFIX)
        for test in TESTS:
            self.assertIn(f"{test} started at the prompt", missing)
        report = verdict(REAL_NEVER_REACHED_PREFIX, reached=False)
        self.assertEqual(report["verdict"], "FAIL")

    def test_a_dropped_completion_breaks_the_count(self):
        # A real transcript minus its final completion line: the
        # equality must name the shortfall even though every other line
        # is present.
        clipped = REAL_MEMORY_PASS_TRANSCRIPT
        index = clipped.rfind("has completed")
        clipped = clipped[:index] + clipped[index + len("has completed"):]
        problems = count_problems(clipped)
        self.assertEqual(
            problems,
            [f"completion count {len(TESTS) - 1} != {len(TESTS)} "
             "driven tests"])


if __name__ == "__main__":
    unittest.main()
